class SecurityMonitor {
private:
    std::vector<SecurityEvent> eventHistory;
    std::mutex historyMutex;
    std::vector<std::function<void(const SecurityEvent&)>> callbacks;
    std::mutex callbackMutex;
    std::atomic<bool> monitoring;
    std::thread monitorThread;
    SeverityLevel minSeverity;
    std::vector<EventType> watchedTypes;

    void processEvent(const SecurityEvent& event) {
        {
            std::lock_guard<std::mutex> lock(historyMutex);
            eventHistory.push_back(event);
            if (eventHistory.size() > 10000) {
                eventHistory.erase(eventHistory.begin());
            }
        }

        if (static_cast<int>(event.severity) < static_cast<int>(minSeverity)) {
            return;
        }

        if (!watchedTypes.empty()) {
            bool found = false;
            for (auto t : watchedTypes) {
                if (t == event.type) {
                    found = true;
                    break;
                }
            }
            if (!found) return;
        }

        std::lock_guard<std::mutex> lock(callbackMutex);
        for (auto& cb : callbacks) {
            cb(event);
        }
    }

    void monitorLoop() {
        while (monitoring) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

public:
    SecurityMonitor() : monitoring(false), minSeverity(SeverityLevel::INFO) {}

    ~SecurityMonitor() {
        stop();
    }

    void start() {
        if (!monitoring) {
            monitoring = true;
            monitorThread = std::thread(&SecurityMonitor::monitorLoop, this);
        }
    }

    void stop() {
        monitoring = false;
        if (monitorThread.joinable()) {
            monitorThread.join();
        }
    }

    void setMinSeverity(SeverityLevel level) {
        minSeverity = level;
    }

    void watchEventType(EventType type) {
        watchedTypes.push_back(type);
    }

    void clearWatchList() {
        watchedTypes.clear();
    }

    void addCallback(std::function<void(const SecurityEvent&)> callback) {
        std::lock_guard<std::mutex> lock(callbackMutex);
        callbacks.push_back(callback);
    }

    void ingestEvent(const SecurityEvent& event) {
        processEvent(event);
    }

    std::vector<SecurityEvent> getHistory() const {
        std::lock_guard<std::mutex> lock(historyMutex);
        return eventHistory;
    }

    std::vector<SecurityEvent> queryHistory(EventType type, SeverityLevel minSev) const {
        std::lock_guard<std::mutex> lock(historyMutex);
        std::vector<SecurityEvent> result;
        for (const auto& event : eventHistory) {
            if (event.type == type && static_cast<int>(event.severity) >= static_cast<int>(minSev)) {
                result.push_back(event);
            }
        }
        return result;
    }

    size_t getEventCount() const {
        std::lock_guard<std::mutex> lock(historyMutex);
        return eventHistory.size();
    }

    void generateAlert(const SecurityEvent& event) {
        std::cout << "[ALERT] " << event.eventId << ": " << event.description << std::endl;
    }
};

class SecurityManager {
private:
    SecurityLogger logger;
    SecurityMonitor monitor;
    std::atomic<bool> running;

public:
    SecurityManager(const std::string& logPath)
        : logger(logPath, true), running(false) {
        monitor.addCallback([this](const SecurityEvent& event) {
            if (event.severity >= SeverityLevel::HIGH) {
                monitor.generateAlert(event);
            }
        });
    }

    void start() {
        running = true;
        monitor.start();
    }

    void stop() {
        running = false;
        monitor.stop();
    }

    void logEvent(EventType type, SeverityLevel severity, const std::string& source,
                  const std::string& description, const std::string& user = "",
                  const std::string& ip = "") {
        SecurityEvent event(type, severity, source, description, user, ip);
        logger.log(event);
        monitor.ingestEvent(event);
    }

    void logAuthentication(const std::string& user, bool success, const std::string& ip) {
        SeverityLevel sev = success ? SeverityLevel::INFO : SeverityLevel::MEDIUM;
        std::string desc = success ? "Successful login" : "Failed login attempt";
        logEvent(EventType::AUTHENTICATION, sev, "AUTH_MODULE", desc, user, ip);
    }

    void logFileAccess(const std::string& user, const std::string& path, const std::string& operation) {
        logEvent(EventType::FILE_ACCESS, SeverityLevel::LOW, "FILE_SYSTEM",
                 operation + " on " + path, user);
    }

    void logPrivilegeEscalation(const std::string& user, const std::string& from, const std::string& to) {
        logEvent(EventType::PRIVILEGE_ESCALATION, SeverityLevel::HIGH, "PRIVILEGE_MANAGER",
                 "User " + user + " escalated from " + from + " to " + to, user);
    }

    void logNetworkConnection(const std::string& sourceIp, const std::string& destIp,
                              int port, const std::string& protocol) {
        logEvent(EventType::NETWORK_CONNECTION, SeverityLevel::INFO, "NETWORK_STACK",
                 "Connection " + sourceIp + " -> " + destIp + ":" + std::to_string(port) +
                 " (" + protocol + ")", "", sourceIp);
    }

    void logIntrusionAttempt(const std::string& ip, const std::string& attackType) {
        logEvent(EventType::INTRUSION_ATTEMPT, SeverityLevel::CRITICAL, "IDS",
                 "Detected " + attackType + " from " + ip, "", ip);
    }

    SecurityMonitor& getMonitor() { return monitor; }
    SecurityLogger& getLogger() { return logger; }
};

int main() {
    SecurityManager manager("security_events.log");
    manager.start();

    manager.logAuthentication("admin", true, "192.168.1.100");
    manager.logAuthentication("guest", false, "10.0.0.55");
