    void ingestEvent(const SecurityEvent& event) {
        processEvent(event);
    }

    std::vector<SecurityEvent> getHistory() const {
        std::lock_guard<std::mutex> lock(historyMutex);
        return eventHistory;
    }

    std::vector<SecurityEvent> queryHistory(EventType type, SeverityLevel minSev) const {
        std::lock_guard<std::mutex> lock(historyMutex);
        std::vector<SecurityEvent> result;
        for (const auto& event : eventHistory) {
            if (event.type == type && static_cast<int>(event.severity) >= static_cast<int>(minSev)) {
                result.push_back(event);
            }
        }
        return result;
    }

    size_t getEventCount() const {
        std::lock_guard<std::mutex> lock(historyMutex);
        return eventHistory.size();
    }

    void generateAlert(const SecurityEvent& event) {
        std::cout << "[ALERT] " << event.eventId << ": " << event.description << std::endl;
    }
