class SecurityManager {
private:
    SecurityLogger logger;
    SecurityMonitor monitor;
    std::atomic<bool> running;

public:
    SecurityManager(const std::string& logPath)
        : logger(logPath, true), running(false) {
        monitor.addCallback([this](const SecurityEvent& event) {
            if (event.severity >= SeverityLevel::HIGH) {
                monitor.generateAlert(event);
            }
        });
    }

    void start() {
        running = true;
        monitor.start();
    }

    void stop() {
        running = false;
        monitor.stop();
